import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import toast from 'react-hot-toast';
import { FiUser, FiPhone, FiLock, FiSave, FiEdit2, FiX, FiPackage, FiCalendar } from 'react-icons/fi';

const Profile = () => {
    const { user, logout } = useAuth();
    const [loading, setLoading] = useState(false);
    const [editMode, setEditMode] = useState(false);
    const [userStats, setUserStats] = useState({ totalProducts: 0, createdAt: '' });
    const [formData, setFormData] = useState({
        name: '',
        phone: '',
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
    });
    const [error, setError] = useState('');

    useEffect(() => {
        if (user) {
            setFormData({
                name: user.name,
                phone: user.phone,
                currentPassword: '',
                newPassword: '',
                confirmPassword: ''
            });
            fetchUserStats();
        }
    }, [user]);

    const fetchUserStats = async () => {
        try {
            // Buscar produtos do usuário se for vendedor
            if (user?.type === 'vendedor') {
                const response = await api.get(`/products/seller/${user.id}`);
                if (response.data.success) {
                    setUserStats({
                        totalProducts: response.data.products.length,
                        createdAt: user.createdAt
                    });
                }
            } else {
                setUserStats({
                    totalProducts: 0,
                    createdAt: user.createdAt
                });
            }
        } catch (error) {
            console.error('Erro ao buscar estatísticas:', error);
        }
    };

    const validateAngolaPhone = (phone) => {
        const cleanPhone = phone.replace(/\D/g, '');
        if (cleanPhone.length === 9 && cleanPhone.startsWith('9')) return true;
        if (cleanPhone.length === 12 && cleanPhone.startsWith('2449')) return true;
        return false;
    };

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
        setError('');
    };

    const handlePhoneChange = (e) => {
        let value = e.target.value.replace(/\D/g, '');
        if (value.length > 9) value = value.slice(0, 9);
        setFormData({ ...formData, phone: value });
    };

    const handleSave = async () => {
        setError('');
        
        if (formData.name.length < 3) {
            setError('Nome deve ter pelo menos 3 caracteres');
            return;
        }
        
        if (formData.phone !== user?.phone && !validateAngolaPhone(formData.phone)) {
            setError('Número de telefone inválido');
            return;
        }
        
        if (formData.newPassword) {
            if (formData.newPassword.length < 6) {
                setError('A nova senha deve ter pelo menos 6 caracteres');
                return;
            }
            if (formData.newPassword !== formData.confirmPassword) {
                setError('As novas senhas não coincidem');
                return;
            }
            if (!formData.currentPassword) {
                setError('Digite sua senha atual');
                return;
            }
        }
        
        setLoading(true);
        
        try {
            const updateData = {
                name: formData.name,
                phone: formData.phone
            };
            
            if (formData.newPassword) {
                updateData.currentPassword = formData.currentPassword;
                updateData.newPassword = formData.newPassword;
            }
            
            const response = await api.put('/auth/profile', updateData);
            
            if (response.data.success) {
                toast.success('Perfil atualizado!');
                user.name = formData.name;
                user.phone = formData.phone;
                localStorage.setItem('techmarket_user', JSON.stringify(user));
                setEditMode(false);
                setFormData({
                    name: formData.name,
                    phone: formData.phone,
                    currentPassword: '',
                    newPassword: '',
                    confirmPassword: ''
                });
            }
        } catch (error) {
            toast.error(error.response?.data?.error || 'Erro ao atualizar');
        } finally {
            setLoading(false);
        }
    };

    const handleCancel = () => {
        setFormData({
            name: user?.name || '',
            phone: user?.phone || '',
            currentPassword: '',
            newPassword: '',
            confirmPassword: ''
        });
        setEditMode(false);
        setError('');
    };

    const formatDate = (dateString) => {
        if (!dateString) return 'Data não disponível';
        const date = new Date(dateString);
        return date.toLocaleDateString('pt-BR', {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        });
    };

    if (!user) return null;

    return (
        <div className="max-w-2xl mx-auto">
            <div className="bg-white rounded-xl shadow-md overflow-hidden">
                <div className="bg-gradient-to-r from-blue-600 to-indigo-600 text-white p-6">
                    <div className="flex items-center justify-between">
                        <div>
                            <h1 className="text-2xl font-bold">Meu Perfil</h1>
                            <p className="opacity-90 mt-1">Gerencie suas informações</p>
                        </div>
                        {!editMode && (
                            <button
                                onClick={() => setEditMode(true)}
                                className="bg-white text-blue-600 px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-gray-100 transition"
                            >
                                <FiEdit2 /> Editar
                            </button>
                        )}
                    </div>
                </div>
                
                <div className="p-6">
                    {error && (
                        <div className="bg-red-50 text-red-600 p-3 rounded-lg mb-4 text-sm">
                            {error}
                        </div>
                    )}
                    
                    <div className="space-y-4">
                        {/* Nome */}
                        <div>
                            <label className="block text-gray-700 mb-2">
                                <FiUser className="inline mr-2" /> Nome
                            </label>
                            {editMode ? (
                                <input
                                    type="text"
                                    name="name"
                                    value={formData.name}
                                    onChange={handleChange}
                                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-blue-500"
                                />
                            ) : (
                                <div className="bg-gray-50 px-3 py-2 rounded-lg text-gray-700">
                                    {user.name}
                                </div>
                            )}
                        </div>
                        
                        {/* Telefone */}
                        <div>
                            <label className="block text-gray-700 mb-2">
                                <FiPhone className="inline mr-2" /> Telefone
                            </label>
                            {editMode ? (
                                <div>
                                    <input
                                        type="tel"
                                        name="phone"
                                        value={formData.phone}
                                        onChange={handlePhoneChange}
                                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-blue-500"
                                        placeholder="923456789"
                                    />
                                    <p className="text-xs text-gray-500 mt-1">Apenas números. Ex: 923456789</p>
                                </div>
                            ) : (
                                <div className="bg-gray-50 px-3 py-2 rounded-lg text-gray-700">
                                    {user.phone}
                                </div>
                            )}
                        </div>
                        
                        {/* Tipo de conta */}
                        <div>
                            <label className="block text-gray-700 mb-2">Tipo de conta</label>
                            <div className="bg-gray-50 px-3 py-2 rounded-lg text-gray-700">
                                {user.type === 'vendedor' ? (
                                    <span className="flex items-center gap-2">
                                        <span className="text-blue-600">👤 Vendedor</span>
                                        <span className="text-xs text-gray-500">- Pode criar anúncios</span>
                                    </span>
                                ) : (
                                    <span className="flex items-center gap-2">
                                        <span className="text-green-600">🛍️ Comprador</span>
                                        <span className="text-xs text-gray-500">- Pode comprar produtos</span>
                                    </span>
                                )}
                            </div>
                        </div>
                        
                        {/* Informações específicas por tipo de conta */}
                        <div className="border-t border-gray-100 pt-4 space-y-3">
                            {user.type === 'vendedor' && (
                                <div>
                                    <label className="block text-gray-700 mb-2">
                                        <FiPackage className="inline mr-2" /> Total de Anúncios
                                    </label>
                                    <div className="bg-blue-50 px-3 py-2 rounded-lg text-blue-700 font-semibold">
                                        {userStats.totalProducts} anúncio(s) publicados
                                    </div>
                                </div>
                            )}
                            
                            <div>
                                <label className="block text-gray-700 mb-2">
                                    <FiCalendar className="inline mr-2" /> Conta criada em
                                </label>
                                <div className="bg-gray-50 px-3 py-2 rounded-lg text-gray-700">
                                    {formatDate(userStats.createdAt || user.createdAt)}
                                </div>
                            </div>
                        </div>
                        
                        {/* Seção de alteração de senha (modo edição) */}
                        {editMode && (
                            <div className="border-t pt-4 mt-4">
                                <h3 className="font-semibold text-gray-800 mb-3">Alterar senha</h3>
                                <div className="space-y-3">
                                    <div>
                                        <label className="block text-gray-700 mb-2">Senha atual</label>
                                        <div className="relative">
                                            <FiLock className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                                            <input
                                                type="password"
                                                name="currentPassword"
                                                value={formData.currentPassword}
                                                onChange={handleChange}
                                                placeholder="Digite sua senha atual"
                                                className="w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg"
                                            />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-gray-700 mb-2">Nova senha</label>
                                        <div className="relative">
                                            <FiLock className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                                            <input
                                                type="password"
                                                name="newPassword"
                                                value={formData.newPassword}
                                                onChange={handleChange}
                                                placeholder="Mínimo 6 caracteres"
                                                className="w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg"
                                            />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-gray-700 mb-2">Confirmar nova senha</label>
                                        <div className="relative">
                                            <FiLock className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                                            <input
                                                type="password"
                                                name="confirmPassword"
                                                value={formData.confirmPassword}
                                                onChange={handleChange}
                                                placeholder="Digite novamente"
                                                className="w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg"
                                            />
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}
                        
                        {/* Botões de ação (modo edição) */}
                        {editMode && (
                            <div className="flex gap-3 mt-6">
                                <button
                                    onClick={handleSave}
                                    disabled={loading}
                                    className="flex-1 bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700 transition flex items-center justify-center gap-2"
                                >
                                    <FiSave /> {loading ? 'Salvando...' : 'Salvar'}
                                </button>
                                <button
                                    onClick={handleCancel}
                                    className="flex-1 bg-gray-200 text-gray-700 py-2 rounded-lg hover:bg-gray-300 transition flex items-center justify-center gap-2"
                                >
                                    <FiX /> Cancelar
                                </button>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Profile;
